-- ─── Bins: 21 around active_bin (8388598..8388618) for each new pool ───────
-- Distributing TVL like the initial pools: top of book bins hold most of TVL_y
-- (SRUB), upper bins hold TVL_x (the asset). Generated programmatically.
DO $$
DECLARE
  pool RECORD;
  bin_offset INT;
  bin_id INT;
  price NUMERIC;
  bin_step_bps INT;
  liquidity BIGINT;
  reserve_x BIGINT;
  reserve_y BIGINT;
BEGIN
  FOR pool IN
    SELECT id, base_price, bin_step, total_tvl_x, total_tvl_y, active_bin_id
    FROM liquidity_pools
    WHERE id::text LIKE 'c0000000-0000-0000-0000-0000000001%'
  LOOP
    bin_step_bps := pool.bin_step;
    FOR bin_offset IN -10..10 LOOP
      bin_id := pool.active_bin_id + bin_offset;
      -- Geometric price ladder: P(i) = base * (1 + step/10000)^i
      price := pool.base_price * power(1.0 + (bin_step_bps::NUMERIC / 10000.0), bin_offset);
      liquidity := (pool.total_tvl_y / 11)::BIGINT;
      IF bin_offset < 0 THEN
        -- Below mid: pure SRUB (token_y)
        reserve_x := 0;
        reserve_y := liquidity;
      ELSIF bin_offset > 0 THEN
        -- Above mid: pure asset (token_x)
        reserve_x := (pool.total_tvl_x / 11)::BIGINT;
        reserve_y := 0;
      ELSE
        -- Active bin: 50/50
        reserve_x := (pool.total_tvl_x / 22)::BIGINT;
        reserve_y := (pool.total_tvl_y / 22)::BIGINT;
        liquidity := reserve_x + reserve_y;
      END IF;
      INSERT INTO pool_bins (pool_id, bin_id, price, liquidity, reserve_x, reserve_y, composition_factor, total_fee_x, total_fee_y, fee_growth_x, fee_growth_y)
      VALUES (pool.id, bin_id, price, liquidity, reserve_x, reserve_y, 0.5, 0, 0, 0, 0)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END LOOP;
END $$;

